export type LocalScreenshot = { url: string; key: string; alt: string | null }

/** Root-relative URL of the bundled screenshot, if the product has one. */
export const localScreenshotUrl = (productId: string): string | null => {
  const stem = stems[productId]
  return stem ? `/screenshots/${stem}.webp` : null
}

